[
  {
    "name": "Siraj at-Thalibin",
    "author": "Syaikh Ihsan Muhammad Dahlan al-Jampasi",
    "desc": "Syarah kitab Minhajul Abidin yang membahas tahapan ibadah dan penyucian jiwa."
  },
  {
    "name": "Al-Fath al-Rabbani wa al-Fayd al-Rahmani",
    "author": "Syaikh Abdul Qadir al-Jilani",
    "desc": "Kumpulan nasihat spiritual dan khotbah penyuci jiwa dari Syekh Abdul Qadir."
  },
  {
    "name": "Sirr al-Asrar fi Ma Yahtaj Ilaih al-Abrar",
    "author": "Syaikh Abdul Qadir al-Jilani",
    "desc": "Panduan tasawuf mendalam mengenai rahasia-rahasia ruhani dan perjalanan spiritual."
  },
  {
    "name": "Risalah al-Mustarsyidin",
    "author": "Al-Harits al-Muhasibi",
    "desc": "Panduan murni akhlak, pengawasan diri (muraqabah), dan mawas diri (muhasabah)."
  },
  {
    "name": "Talbis Iblis",
    "author": "Ibn al-Jauzi",
    "desc": "Peringatan atas tipu daya Iblis yang sering mengecoh ahli ibadah dan penuntut ilmu."
  },
  {
    "name": "Shifatus Safwah",
    "author": "Ibn al-Jauzi",
    "desc": "Kisah keteladanan, akhlak, dan kepribadian para Nabi, Sahabat, dan wali Allah."
  },
  {
    "name": "Dhamm al-Hawa",
    "author": "Ibn al-Jauzi",
    "desc": "Kajian mendalam tentang bahaya memperturutkan hawa nafsu dan cara menundukkannya."
  },
  {
    "name": "Tanbih al-Mughtarrin",
    "author": "Abdul Wahhab asy-Sya'rani",
    "desc": "Peringatan bagi orang-orang terperdaya agar kembali pada akhlak Salafush Shalih."
  },
  {
    "name": "Lawaqih al-Anwar al-Qudsiyyah",
    "author": "Abdul Wahhab asy-Sya'rani",
    "desc": "Prinsip etika spiritual dan ikrar janji para sufi dalam menjaga ketaatan."
  },
  {
    "name": "Al-Bahr al-Mawrud fi al-Mawathiq wa al-'Uhud",
    "author": "Abdul Wahhab asy-Sya'rani",
    "desc": "Komitmen spiritual dan janji-janji akhlak sufi dalam menjalani kehidupan bermasyarakat."
  },
  {
    "name": "Miftah al-Falah wa Misbah al-Arwah",
    "author": "Ibn 'Ata'illah al-Iskandari",
    "desc": "Keutamaan zikir dan tata cara pembersihan jiwa untuk mendekatkan diri kepada Allah."
  },
  {
    "name": "Al-Qasdh al-Mujarrad fi Ma'rifat al-Ism al-Mufrad",
    "author": "Ibn 'Ata'illah al-Iskandari",
    "desc": "Pembahasan tasawuf mengenai rahasia dan keagungan nama Allah (Lafdzul Jalalah)."
  },
  {
    "name": "Mizan al-'Amal",
    "author": "Abu Hamid al-Ghazali",
    "desc": "Timbangan amal untuk mencapai kebahagiaan akhlak dan keseimbangan keilmuan."
  },
  {
    "name": "Raudhat at-Thalibin wa 'Umdat al-Salikin",
    "author": "Abu Hamid al-Ghazali",
    "desc": "Panduan praktis bagi penempuh jalan spiritual menuju ma'rifatullah."
  },
  {
    "name": "Kimiya' as-Sa'adah",
    "author": "Abu Hamid al-Ghazali",
    "desc": "Kajian tentang alkimia kebahagiaan sejati melalui pengenalan diri dan Tuhan."
  },
  {
    "name": "Taisir al-Khallaq fi 'Ilm al-Akhlaq",
    "author": "Hafizh Hasan al-Mas'udi",
    "desc": "Ringkasan dasar-dasar ilmu akhlak mulia bagi para pelajar pemula."
  },
  {
    "name": "Al-Akhlaq li al-Banin",
    "author": "Umar bin Ahmad Baradja",
    "desc": "Panduan akhlak terapan sehari-hari untuk anak-anak dan pemuda Muslim."
  },
  {
    "name": "Wasaya al-Aba' lil Abna'",
    "author": "Muhammad Syakir al-Iskandari",
    "desc": "Wasiat dan nasihat orang tua kepada anak tentang pembentukan karakter islami."
  },
  {
    "name": "Al-Madkhal",
    "author": "Ibn al-Hajj al-Abdari",
    "desc": "Pedoman perilaku, etika pergaulan, dan larangan bid'ah dalam keseharian."
  },
  {
    "name": "Kitab az-Zuhd",
    "author": "Abdullah bin al-Mubarak",
    "desc": "Kumpulan riwayat salaf tentang kesederhanaan, kerendahan hati, dan zuhud."
  },
  {
    "name": "Kitab az-Zuhd",
    "author": "Ahmad bin Hanbal",
    "desc": "Himpunan atsar salafus shalih mengenai perilaku tidak silau dunia."
  },
  {
    "name": "Makarim al-Akhlaq",
    "author": "Ibn Abi ad-Dunya",
    "desc": "Kumpulan hadis dan riwayat tentang keluhuran budi pekerti manusia."
  },
  {
    "name": "Al-Sabil al-Maddakar",
    "author": "Habib Abdullah bin Alawi al-Haddad",
    "desc": "Peringatan dan dorongan spiritual untuk memperbanyak bekal akhirat."
  },
  {
    "name": "Al-Fusul al-Ilmiyyah wa al-Usul al-Imaniyyah",
    "author": "Habib Abdullah bin Alawi al-Haddad",
    "desc": "Prinsip-prinsip keimanan, penyucian hati, dan penyempurnaan akhlak."
  },
  {
    "name": "Al-Mabahith al-Asliyyah",
    "author": "Ahmad bin 'Ajiba",
    "desc": "Syarah atas kaidah-kaidah ilmu tasawuf dan tata cara tazkiyatun nufs."
  },
  {
    "name": "Al-Mi'raj ila Ma'arij al-Tasawwuf",
    "author": "Ahmad bin 'Ajiba",
    "desc": "Tangga naik spiritual dan tahapan maqamat dalam jalan sufi."
  },
  {
    "name": "Al-Hadiqat an-Nadiyyah",
    "author": "Abdul Ghani an-Nablusi",
    "desc": "Syarah rinci mengenai penyucian jiwa dan etika dalam At-Thariqah al-Muhammadiyyah."
  },
